def poly(x, d):
    import itertools
    return np.column_stack([np.prod(x[:, idx], axis=1) for k in range(d + 1) for idx in itertools.combinations_with_replacement(range(x.shape[1]), k)])

def pairs(x):
    import itertools
    return np.column_stack([x[:, i] * x[:, j] for (i, j) in itertools.combinations_with_replacement(range(x.shape[1]), 2)])

def _paired_design(q, frequency):
    z = np.roll(q, -2, axis=1)
    return np.stack([np.ones_like(q), q, np.sin(frequency * z), z, q * q, q ** 3, z * z, q * z], axis=-1)
